/*
 * A042211  Denominators of continued fraction convergents to sqrt(631).
 * https://oeis.org/A042211
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = denominator of the nth convergent for sqrt(631)
 * Range:     u8 n <= 5, u16 n <= 8, u32 n <= 22, u64 n <= 43, u128 n <= 82,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The convergents of sqrt(631) are generated by its continued fraction
   expansion.  We use the standard recurrence:
        m_{k+1} = d_k*a_k - m_k
        d_{k+1} = (D - m_{k+1}^2) / d_k
        a_{k+1} = floor((a0 + m_{k+1}) / d_{k+1})
   with D = 631 and a0 = floor(sqrt(631)) = 25.
   The denominators q_k of the convergents satisfy
        q_{-2} = 1, q_{-1} = 0,
        q_k = a_k * q_{k-1} + q_{k-2}          (k ≥ 0).  */

#include <stdbool.h>

seq_t a(idx_t n)
{
    /* constants for sqrt(631) */
    const idx_t D = 631;
    const idx_t a0 = 25;

    /* continued fraction state variables */
    idx_t m = 0;              /* m_0 */
    idx_t d = 1;              /* d_0 */
    idx_t a_prev = a0;        /* a_0 */

    /* denominator recurrence state */
    seq_t q_prev2 = (seq_t)1; /* q_{-2} */
    seq_t q_prev1 = (seq_t)0; /* q_{-1} */
    seq_t q_cur = 0;          /* q_k */

    for (idx_t k = 0; k <= n; ++k) {
        seq_t a_k = (seq_t)a_prev;   /* a_k as seq_t */

        /* Compute next denomination */
        q_cur = a_k * q_prev1 + q_prev2;

        if (k == n) {
            return q_cur;
        }

        /* Advance recurrence */
        q_prev2 = q_prev1;
        q_prev1 = q_cur;

        /* Compute next partial quotient a_{k+1} for next iteration */
        m = d * a_prev - m;
        d = (D - m * m) / d;
        a_prev = (idx_t)((a0 + m) / d);
    }

    /* Should never reach here; return 0 as fallback */
    return (seq_t)0;
}
